// the range of `table` holding `c` in tables that are sorted and disjoint
fn find(table: &[(u32, u32)], c: char) -> Option<usize> {
    use core::cmp::Ordering::*;
    let c = c as u32;
    table.binary_search_by(|&(lo, hi)| if hi < c { Less } else if lo > c { Greater } else { Equal }).ok()
}

// character classes of unicode 17 where ascii answers without the tables
pub fn is_digit(c: char) -> bool { if c.is_ascii() { c.is_ascii_digit() } else { find(&DIGIT, c).is_some() } }
pub fn is_alpha(c: char) -> bool { if c.is_ascii() { c.is_ascii_alphabetic() } else { find(&ALPHA, c).is_some() } }
pub fn is_numeric(c: char) -> bool { if c.is_ascii() { c.is_ascii_digit() } else { find(&NUMERIC, c).is_some() } }
pub fn is_alnum(c: char) -> bool { is_alpha(c) || is_numeric(c) }

// a character a repr shows as itself where the space is the only separator
pub fn is_printable(c: char) -> bool { if c.is_ascii() { (' '..='~').contains(&c) } else { find(&UNPRINTABLE, c).is_none() } }

// white space as unicode names it for splitting and stripping
pub fn is_space(c: char) -> bool { c.is_whitespace() }

// unicode white space with the four information separators a runtime may add
pub fn is_space_or_separator(c: char) -> bool { c.is_whitespace() || ('\x1c'..='\x1f').contains(&c) }

// a decimal digit of any script is worth its offset mod 10 in its run
pub fn decimal_value(c: char) -> Option<u32> {
    if c.is_ascii_digit() { return Some(c as u32 - '0' as u32); }
    find(&DECIMAL, c).map(|i| (c as u32 - DECIMAL[i].0) % 10)
}

// the titlecase of `c` which is its uppercase unless the table says otherwise
pub fn push_title(out: &mut alloc::string::String, c: char) {
    if c.is_ascii() { return out.push(c.to_ascii_uppercase()); }
    match TITLE.binary_search_by_key(&(c as u32), |&(k, _)| k) {
        Ok(i) => out.push_str(TITLE[i].1),
        Err(_) => out.extend(c.to_uppercase()),
    }
}

// full casefold so ß gives ss
pub fn push_fold(out: &mut alloc::string::String, c: char) {
    if c.is_ascii() { return out.push(c.to_ascii_lowercase()); }
    let n = c as u32;
    if let Ok(i) = FOLD.binary_search_by_key(&n, |&(k, _)| k as u32) {
        let start = if i == 0 { 0 } else { FOLD[i - 1].1 as usize };
        return out.push_str(&FOLDS[start..FOLD[i].1 as usize]);
    }
    match FOLD_RUNS.iter().find(|&&(lo, hi, _)| (lo as u32..=hi as u32).contains(&n)) {
        Some(&(_, _, k)) => out.extend(char::from_u32(n.wrapping_add_signed(k))),
        None => c.to_lowercase().for_each(|l| out.push(l)),
    }
}

// a titlecase letter such as `ǅ` neither upper nor lower but its own titlecase
pub fn is_titlecase(c: char) -> bool {
    !c.is_ascii() && !c.is_lowercase() && !c.is_uppercase()
        && TITLE.binary_search_by_key(&(c as u32), |&(k, _)| k).is_ok_and(|i| TITLE[i].1.chars().eq(core::iter::once(c)))
}

// a character with case as title casing reads words as runs of them
pub fn is_cased(c: char) -> bool { if c.is_ascii() { c.is_ascii_alphabetic() } else { c.is_uppercase() || c.is_lowercase() || is_titlecase(c) } }

// number text trimmed by `space` with the digits `D` reads as ascii digits
pub fn number_text<D: Digits>(s: &str, space: impl FnMut(char) -> bool) -> alloc::borrow::Cow<'_, str> {
    let t = s.trim_matches(space);
    if t.is_ascii() { return t.into(); }
    t.chars().map(|c| D::value(c).map_or(c, |d| char::from(b'0' + d as u8))).collect::<alloc::string::String>().into()
}

/* which characters count as digits and the value a number reads off each */
pub trait Digits: 'static {
    fn is(c: char) -> bool;
    fn value(c: char) -> Option<u32>;
}

/* the ascii digits alone */
pub struct Ascii;

/* the decimal digits of every script */
pub struct Decimal;

/* the decimals and the other digit characters such as superscripts */
pub struct Digit;

/* every character with a numeric value */
pub struct Numeric;

impl Digits for Ascii {
    fn is(c: char) -> bool { c.is_ascii_digit() }
    fn value(c: char) -> Option<u32> { c.to_digit(10) }
}

impl Digits for Decimal {
    fn is(c: char) -> bool { decimal_value(c).is_some() }
    fn value(c: char) -> Option<u32> { decimal_value(c) }
}

impl Digits for Digit {
    fn is(c: char) -> bool { is_digit(c) }
    fn value(c: char) -> Option<u32> { decimal_value(c) }
}

impl Digits for Numeric {
    fn is(c: char) -> bool { is_numeric(c) }
    fn value(c: char) -> Option<u32> { decimal_value(c) }
}
